def safe_divide_batch(pairs):
    results = []
    for a, b in pairs:
        try:
            results.append(a / b)
        except ZeroDivisionError:
            results.append(None)
    return results

import time

def retry_with_backoff(fn, max_attempts=3):
    attempt = 0
    while attempt < max_attempts:
        try:
            return fn()
        except Exception:
            attempt += 1
            if attempt == max_attempts:
                raise
            time.sleep(0.01 * attempt)

import subprocess

def run_checked(argv):
    completed = subprocess.run(
        argv,
        shell=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE
    )
    if completed.returncode != 0:
        raise RuntimeError(completed.stderr.decode())
    return completed.stdout.decode().strip()

def nested_lookup(data, path, default=None):
    """Walk a dotted path through nested dicts, returning default if absent."""
    if path == "":
        return data
    current = data
    for part in path.split('.'):
        if not isinstance(current, dict):
            return default
        if part not in current:
            return default
        current = current[part]
    return current

def nested_lookup(data, path, default=None):
    """Walk a dotted path through nested dicts, returning default if absent.

    This function traverses nested dictionaries using a dotted path string
    (e.g., ``"a.b.c"``). It correctly handles falsy values (0, '', False)
    and non-dict intermediate values, returning ``default`` when the path
    does not exist or a non-dict is encountered before the final part.
    """
    if not path:
        return data

    current = data
    for part in path.split('.'):
        if isinstance(current, dict):
            if part in current:
                current = current[part]
            else:
                return default
        else:
            return default
    return current
